files.common.glsl:
// CYBERPUNK kit common helpers.
// Procedural block glyph (5x7 bit grid) for id g; cell coords c in 0..1. Not any real alphabet.
float CP_glyph(vec2 c, float g) {
  if (c.x < 0.0 || c.y < 0.0 || c.x >= 1.0 || c.y >= 1.0) return 0.0;
  vec2 b = floor(c * vec2(5.0, 7.0));
  float bit = h21(vec2(g * 13.0 + b.x, b.y + g * 7.0));
  // symmetric-ish structure reads as a glyph rather than noise
  float mirror = h21(vec2(g * 13.0 + (4.0 - b.x), b.y + g * 7.0));
  float on = step(0.52, b.x < 2.0 ? bit : (b.x > 2.0 ? mirror : h21(vec2(g, b.y))));
  vec2 f = fract(c * vec2(5.0, 7.0));
  return on * step(0.12, f.x) * step(0.12, f.y);
}
// Neon source scene shared by the signal-damage styles. mode 0 city bokeh, 1 test bars, 2 neon grid.
vec3 CP_scene(vec2 uv, int mode) {
  vec2 A = M_asp() * 0.5;
  vec3 col = vec3(0.0);
  if (mode == 1) {
    float x = (uv.x + A.x) / (2.0 * A.x);
    float bar = floor(x * 7.0);
    vec3 bars[7] = vec3[7](u_ink, u_a2, u_a1, u_a0, mix(u_a0, u_a1, 0.5), mix(u_a1, u_a2, 0.5), u_bg * 0.5 + 0.02);
    col = bars[int(clamp(bar, 0.0, 6.0))] * 0.9;
    if (uv.y < -A.y * 0.45) col = mix(u_bg * 0.3, u_ink, x) * 0.9;
    // moving disc
    vec2 c = vec2(0.45 * lsin(1.0, 0.0) * A.x, 0.1 * lsin(2.0, 0.25));
    col = mix(col, u_a0 * 1.2, 1.0 - smoothstep(0.1, 0.105, length(uv - c)));
    return col;
  }
  if (mode == 2) {
    // neon perspective grid + sun
    float hz = -0.02;
    if (uv.y < hz) {
      float z = 0.12 / (hz - uv.y + 0.001);
      vec2 g = vec2(uv.x * z * 2.0, z + u_p * 4.0);
      vec2 gf = abs(fract(g) - 0.5);
      float ln = max(1.0 - smoothstep(0.0, 0.04 * z, gf.x), 1.0 - smoothstep(0.0, 0.04 * z, gf.y));
      col = u_a0 * ln * exp(-z * 0.06) * 1.3 + u_a1 * 0.08;
    } else {
      float s = length(uv - vec2(0.0, 0.18)) - 0.22;
      float bands = step(0.5, fract((uv.y - 0.1) * 18.0 - u_p * 2.0)) + step(0.25, uv.y);
      col = mix(u_a1, u_a2, sat((uv.y + 0.1) * 2.5)) * (1.0 - smoothstep(0.0, 0.003, s)) * min(bands, 1.0) * 1.2;
      col += u_a1 * 0.25 * exp(-max(s, 0.0) * 8.0) + mix(u_bg, u_a1 * 0.3, sat(1.0 - uv.y * 2.0)) * 0.6;
    }
    return col;
  }
  // city bokeh: out-of-focus lights and signage blocks
  col = mix(u_bg, u_a1 * 0.1 + u_a0 * 0.04, sat(0.5 - uv.y));
  for (int i = 0; i < 26; i++) {
    vec3 h = h33(vec3(float(i), 3.0, 1.0));
    vec2 p = (h.xy - 0.5) * A * 2.2 + vec2(0.04 * lsin(1.0, h.z), 0.0);
    float r = 0.02 + 0.07 * h.z;
    float d = length(uv - p) - r;
    col += accent(floor(h.x * 3.0)) * (1.0 - smoothstep(-0.01, 0.01, d)) * (0.35 + 0.4 * h.y) * (0.75 + 0.25 * smoothstep(-r, 0.0, d));
  }
  for (int i = 0; i < 5; i++) {
    vec3 h = h33(vec3(float(i), 8.0, 2.0));
    vec2 p = (h.xy - 0.5) * A * 1.6;
    vec2 s = vec2(0.05 + 0.12 * h.z, 0.03 + 0.03 * h.x);
    float d = sdBox(uv - p, s);
    col += accent(float(i)) * (1.0 - smoothstep(0.0, 0.004, abs(d) - 0.004)) * 1.4 + accent(float(i)) * exp(-max(d, 0.0) * 30.0) * 0.25;
  }
  return col;
}
// Bayer 4x4 threshold.
float CP_bayer(vec2 fc) {
  ivec2 p = ivec2(mod(fc, 4.0));
  int i = p.x + p.y * 4;
  int m[16] = int[16](0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5);
  return (float(m[i]) + 0.5) / 16.0;
}

files.styles/ar-overlay.glsl:
// AR Overlay — an augmented-reality HUD tracks moving targets over a blurred city: reticles, data tags, rings, tapes and readouts.
vec2 AR_target(float i) {
  vec3 h = h33(vec3(i, 6.0, 3.0));
  vec2 A = M_asp() * 0.5;
  return vec2((h.x - 0.5) * A.x * 1.5 + 0.12 * lsin(1.0, h.z), (h.y - 0.5) * A.y * 1.2 + 0.06 * lsin(2.0, h.x));
}
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  vec3 col = CP_scene(uv, 0) * 0.35 * p_background;
  vec3 hud = mix(u_a0, u_ink, 0.2);
  float px = aa();
  // central rotating rings with ticks
  float r = length(uv), a = atan(uv.y, uv.x);
  float spin = TAU * u_p * float(p_speed);
  float ring1 = line(abs(r - 0.18), 0.002) * step(0.5, fract((a + spin) / TAU * 3.0 + 0.1));
  float ticks = line(abs(r - 0.21), 0.012) * step(0.8, fract((a - spin * 0.5) / TAU * 72.0));
  float ring2 = line(abs(r - 0.25), 0.0015) * step(0.2, fract((a - spin) / TAU * 5.0));
  col += hud * (ring1 + ticks * 0.8 + ring2 * 0.6) * p_rings;
  // compass tape at the top
  float tapeY = A.y - 0.06;
  if (abs(uv.y - tapeY) < 0.03) {
    float hx = uv.x * 8.0 + u_p * float(p_speed) * 8.0;
    float tk = step(0.92, fract(hx)) * step(abs(uv.y - tapeY), 0.01 + 0.01 * step(0.5, fract(hx / 4.0)));
    col += hud * tk * p_tape;
  }
  col += hud * line(abs(uv.x), 0.002) * step(abs(uv.y - tapeY), 0.035) * p_tape;
  // target reticles with tags and leader lines
  for (int i = 0; i < 8; i++) {
    if (i >= p_targets) break;
    float fi = float(i);
    vec2 tp = AR_target(fi);
    vec2 q = uv - tp;
    float s = 0.035 + 0.01 * sin(TAU * (u_p * float(p_speed) * 2.0 + fi * 0.3));
    vec2 aq = abs(q);
    float corners = (step(aq.x, s) * step(s - 0.002, aq.x) + step(aq.y, s) * step(s - 0.002, aq.y)) * step(s * 0.55, max(aq.x, aq.y));
    float dot_ = 1.0 - smoothstep(0.004, 0.004 + px, length(q));
    vec3 tc = h11(fi + 2.0) < 0.3 ? u_a1 : hud;
    col += tc * (corners + dot_) * 1.2;
    // leader + tag
    vec2 tagP = tp + vec2(0.09, 0.06) * (h11(fi) < 0.5 ? 1.0 : -1.0);
    col += tc * line(sdSeg(uv, tp + normalize(tagP - tp) * s * 1.2, tagP), 0.0015) * 0.8;
    vec2 tq = uv - tagP;
    float dir = sign(tagP.x - tp.x);
    float bars = 0.0;
    for (int b = 0; b < 3; b++) { float w = 0.02 + 0.05 * h11(fi * 3.0 + float(b) + floor(tslot(6.0))); bars += step(0.0, tq.x * dir) * step(tq.x * dir, w) * step(abs(tq.y + float(b) * 0.009), 0.0022); }
    col += tc * bars * p_tags;
    // distance readout bar that fills
    float fillv = fract(u_p * float(p_speed) + h11(fi));
    col += tc * 0.8 * step(0.0, tq.x * dir) * step(tq.x * dir, 0.07 * fillv) * step(abs(tq.y - 0.012), 0.0015) * p_tags;
  }
  // waveform readout bottom-left
  vec2 wq = uv - vec2(-A.x + 0.2, -A.y + 0.08);
  if (abs(wq.x) < 0.16 && abs(wq.y) < 0.05) {
    float w = 0.025 * sin(wq.x * 60.0 + spin * 3.0) * sin(wq.x * 13.0 - spin);
    col += hud * line(abs(wq.y - w), 0.0015) * p_readouts + hud * 0.3 * line(abs(abs(wq.y) - 0.05), 0.001) * p_readouts;
  }
  // bar graph bottom-right
  vec2 bq = uv - vec2(A.x - 0.2, -A.y + 0.04);
  if (bq.x > -0.14 && bq.x < 0.14 && bq.y > 0.0 && bq.y < 0.1) {
    float bi = floor((bq.x + 0.14) / 0.02);
    float hgt = 0.02 + 0.08 * (0.5 + 0.5 * sin(TAU * (u_p * float(p_speed) * 2.0 + bi * 0.17)));
    col += mix(hud, u_a1, step(0.07, hgt)) * step(bq.y, hgt) * step(0.004, fract((bq.x + 0.14) / 0.02) * 0.02) * p_readouts;
  }
  // frame corners + scan line
  vec2 fq = abs(uv) - (A - 0.03);
  col += hud * 0.8 * ((step(-0.08, fq.x) * step(abs(fq.y), 0.0015)) + (step(-0.08, fq.y) * step(abs(fq.x), 0.0015))) * step(fq.x, 0.002) * step(fq.y, 0.002);
  col += hud * 0.15 * pulse((uv.y + A.y) / (2.0 * A.y), float(p_speed), 0.0, 0.01) * p_scan;
  col = aces(col * 1.2);
  return vec4(col, max(max(col.r, col.g), col.b) * 0.0 + 1.0);
}

files.styles/bit-crush.glsl:
// Bit Crush (pass 2) — the image collapses in bit depth: ordered dither, palette snapping and pixel blocks breathe with the loop.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  // crush level breathes over the loop, bands can crush independently
  float band = floor(fc.y / (u_res.y / float(p_bands)));
  float lvl = sat(p_crush + 0.35 * p_breathe * lsin(1.0, band * 0.13));
  float px = floor(1.0 + lvl * 14.0 * p_pixelate);
  vec2 cell = floor(fc / px) * px + px * 0.5;
  vec3 c = texture(u_buf0, cell / u_res).rgb;
  float bits = mix(6.0, 1.0, lvl);
  float levels = pow(2.0, floor(bits));
  float th = CP_bayer(floor(fc / px)) - 0.5;
  vec3 q = floor(c * (levels - 1.0) + 0.5 + th * p_dither) / (levels - 1.0);
  // optional palette snap to the kit palette
  if (p_paletteSnap) {
    vec3 cand[5] = vec3[5](u_bg, u_ink, u_a0, u_a1, u_a2);
    float best = 1e9; vec3 bc = q;
    for (int i = 0; i < 5; i++) { float d = distance(c + th * 0.25 * p_dither, cand[i]); if (d < best) { best = d; bc = cand[i]; } }
    q = bc;
  }
  vec3 col = sat(q);
  // scan glitch rows (limited)
  float g = step(0.97, h21(vec2(band, tslot(12.0))));
  col = mix(col, col.gbr, g * p_glitch);
  return vec4(col, 1.0);
}

files.styles/chrome-liquid.glsl:
// Chrome Liquid — mercury metaballs merge and split, mirroring a neon room in their polished skin.
vec3 CL_env(vec3 d) {
  // neon strip room: vertical and horizontal tubes on dark walls
  float a = atan(d.z, d.x), e = d.y;
  float strips = pow(0.5 + 0.5 * cos(a * float(p_strips)), 60.0);
  float bands = exp(-pow((e - 0.35) * 30.0, 2.0)) + exp(-pow((e + 0.2) * 40.0, 2.0)) * 0.6;
  vec3 c = accent(floor((a + PI) / TAU * float(p_strips))) * strips * 1.4 + mix(u_a0, u_a1, 0.5 + 0.5 * sin(a * 2.0)) * bands * 1.2;
  c += mix(u_bg, u_a2 * 0.2, sat(e + 0.5)) * 0.6;
  c += u_ink * pow(sat(e), 40.0) * 2.0;                 // overhead softbox
  return c;
}
float CL_map(vec3 p) {
  float d = 1e9;
  for (int i = 0; i < 8; i++) {
    if (i >= p_blobs) break;
    vec3 h = h33(vec3(float(i), 3.0, 7.0));
    vec3 c = vec3(0.45 * cos(TAU * (u_p * float(p_speed) * (h.x < 0.5 ? 1.0 : 2.0) + h.y)), 0.25 * sin(TAU * (u_p * float(p_speed) + h.z)), 0.3 * sin(TAU * (u_p * float(p_speed) * (h.z < 0.5 ? 1.0 : 2.0) + h.x))) * p_spread;
    float r = 0.16 + 0.12 * h.z;
    d = smin(d, length(p - c) - r, 0.18 * p_viscosity + 0.02);
  }
  d += 0.004 * p_ripple * sin(p.x * 40.0 + TAU * u_p * 3.0) * sin(p.y * 40.0);
  return d;
}
vec4 motif(vec2 uv, vec2 fc) {
  float ang = 0.3 * lsin(1.0, 0.0) * p_orbit;
  vec3 ro = vec3(sin(ang) * 2.2, 0.2, cos(ang) * 2.2);
  vec3 fw = normalize(-ro), rt = normalize(cross(vec3(0.0, 1.0, 0.0), fw)), up = cross(fw, rt);
  vec3 rd = normalize(fw * 1.8 + uv.x * rt + uv.y * up);
  float t = 0.8, hit = 0.0;
  for (int i = 0; i < 80; i++) { float d = CL_map(ro + rd * t); if (d < 0.001) { hit = 1.0; break; } t += d; if (t > 5.0) break; }
  vec3 col; float a;
  if (hit > 0.0) {
    vec3 p = ro + rd * t;
    vec2 e = vec2(0.0015, -0.0015);
    vec3 n = normalize(e.xyy * CL_map(p + e.xyy) + e.yyx * CL_map(p + e.yyx) + e.yxy * CL_map(p + e.yxy) + e.xxx * CL_map(p + e.xxx));
    vec3 r = reflect(rd, n);
    float fres = 0.6 + 0.4 * pow(1.0 - sat(dot(n, -rd)), 5.0);
    vec3 tint = mix(vec3(1.0), u_a2 + 0.5, 0.25 * p_tint);
    col = CL_env(r) * fres * tint;
    // second bounce hint
    col += CL_env(reflect(r, n)) * 0.08;
    a = 1.0;
  } else {
    col = CL_env(rd) * 0.12 * p_room;
    a = 0.0;
  }
  col = aces(col * 1.1);
  return vec4(col, max(a, max(max(col.r, col.g), col.b)));
}

files.styles/cipher-fall.glsl:
// Cipher Fall — cascades of invented glyphs pour down in depth layers, heads burning bright, tails decaying.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  vec3 col = vec3(0.0);
  for (int l = 0; l < 3; l++) {
    if (l >= p_layers) break;
    float fl = float(l);
    float gs = (0.035 - fl * 0.008) * p_glyphSize;       // glyph cell height
    vec2 cell = vec2(gs * 0.72, gs);
    vec2 q = uv + vec2(fl * 0.013, 0.0);
    vec2 id = floor(q / cell);
    vec2 f = fract(q / cell);
    vec3 h = h33(vec3(id.x, fl, 3.0));
    if (h.x > p_density) continue;
    // the column's stream: head position falls an integer number of wraps per loop
    float rows = ceil(2.0 * A.y / cell.y) + 1.0;
    float speed = float(p_speed) * (1.0 + floor(h.y * 3.0));
    float tailLen = 6.0 + 18.0 * p_tail;
    float head = fract(h.z + u_p * speed) * (rows + tailLen);
    float r = floor((A.y - q.y) / cell.y);
    float fromHead = head - r;
    float trail = fromHead >= 0.0 ? exp(-fromHead / (tailLen * 0.35)) : 0.0;
    // glyph changes over time (slots, limited)
    float gid = floor(h21(id * 1.3) * 64.0) + floor(tslot(18.0 * p_mutate + 1.0) * step(0.7, h21(id + 5.0)));
    float g = CP_glyph(f * vec2(1.1, 1.05) - vec2(0.05, 0.02), gid);
    float isHead = fromHead >= 0.0 && fromHead < 1.0 ? 1.0 : 0.0;
    vec3 base = p_colourMode == COLOUR_MODE_ACCENTS ? accent(id.x) : u_a0;
    vec3 c = mix(base, u_ink, isHead * 0.85) * (isHead * 1.6 * p_headGlow + trail);
    float depth = 1.0 - fl * 0.35;
    col += c * g * depth * (fl == 0.0 ? 1.0 : 0.6) + u_a0 * trail * 0.04 * depth * p_glow;
  }
  col = aces(col * 1.2);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/circuit-growth.glsl:
// Circuit Growth — traces autoroute across a board at 45 degrees, vias bloom, and current pulses race home.
vec4 motif(vec2 uv, vec2 fc) {
  float sc = 16.0 * p_density;
  vec2 p = uv * sc;
  vec2 id = floor(p), f = fract(p) - 0.5;
  vec3 h = h33(vec3(id, 1.0));
  // tile types: straight, 45-degree bend, via, empty (truchet PCB)
  float d = 1e9; float along = 0.0;
  float type = floor(h.x * 4.0);
  float r = floor(h.y * 4.0);
  vec2 q = f;
  for (float k = 0.0; k < 4.0; k++) if (k < r) q = vec2(-q.y, q.x);
  if (type < 1.0) { d = abs(q.y); along = q.x + 0.5; }
  else if (type < 2.0) { d = min(sdSeg(q, vec2(-0.5, 0.0), vec2(0.0, 0.0)), sdSeg(q, vec2(0.0, 0.0), vec2(0.5, 0.5))); along = q.x + 0.5; }
  else if (type < 3.0) { d = min(abs(q.y), abs(q.x)); along = max(abs(q.x), abs(q.y)); }
  else { d = sdSeg(q, vec2(-0.5, 0.0), vec2(0.0, 0.0)); along = q.x + 0.5; }
  bool via = h.z < 0.18 * p_vias;
  // growth: a wavefront spreading from routed sources, retracts at the end of the loop
  float g = growEnv(0.4) * (1.6 * p_reach);
  float wave = 0.0;
  float src = 1e9;
  for (int i = 0; i < 4; i++) { if (i >= p_sources) break; vec2 s = (h22(vec2(float(i), 6.0)) - 0.5) * M_asp() * 0.9; src = min(src, length(uv - s) + 0.08 * abs(ln2(uv * 3.0 + float(i), 1.0, 0.2))); }
  float grown = smoothstep(g, g - 0.05, src);
  float front = exp(-pow((src - g) * 40.0, 2.0)) * step(0.02, g);
  float w = 0.07 * p_traceWidth;
  float trace = (1.0 - smoothstep(w, w + 0.04, d)) * grown;
  float pr = 0.18 * p_padSize; float pad = via ? (1.0 - smoothstep(pr - 0.02, pr + 0.02, length(f))) * (smoothstep(pr * 0.35, pr * 0.55, length(f))) * grown : 0.0;
  // current pulses along the traces (direction by tile)
  float pl = pulse(along * 0.25 + (id.x + id.y) * 0.25, float(p_current), 0.0, 0.05) * trace;
  vec3 board = u_bg + u_a2 * 0.05 * (0.5 + 0.5 * ln2(uv * 30.0, 1.0, 0.1)) * p_substrate;
  vec3 copper = mix(u_a2 * 0.8, u_a0, 0.3);
  vec3 col = board + copper * trace * 0.7 + u_ink * pad * 0.8 + u_a0 * pl * 1.8 + u_a1 * front * trace * 2.0 + u_a0 * glow2(d, 0.12) * 0.1 * grown * p_glow;
  // solder mask texture
  col *= 0.92 + 0.08 * h21(floor(fc / 2.0));
  col = aces(col * 1.1);
  return vec4(col, 1.0);
}

files.styles/crt-burn.glsl:
// CRT Burn (pass 3) — curved glass, shadow mask, scanlines, halation and phosphor burn-in.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 t = fc / u_res;
  vec2 c = t * 2.0 - 1.0;
  // barrel distortion
  float k = 0.12 * p_curvature;
  vec2 cd = c * (1.0 + k * dot(c, c));
  vec2 st = cd * 0.5 + 0.5;
  float inside = step(0.0, st.x) * step(st.x, 1.0) * step(0.0, st.y) * step(st.y, 1.0);
  vec3 src = texture(u_buf0, st).rgb;
  vec3 ghost = texture(u_buf1, st).rgb;
  // burn-in: a static layout etched into the phosphor (from the source at a fixed phase is not available, use a frame grid)
  vec3 col = src + ghost * 0.5 * p_persistence;
  // halation: wide blur of bright parts
  vec3 hal = vec3(0.0);
  for (int i = 0; i < 12; i++) { float a = float(i) * 0.5236; hal += texture(u_buf0, st + vec2(cos(a), sin(a)) * 0.012 * p_halation).rgb; }
  col += max(hal / 12.0 - 0.2, 0.0) * 0.8 * p_halation;
  // scanlines (beam profile)
  float lines = u_res.y / (2.0 + 2.0 * p_scanlines);
  float sl = 0.5 + 0.5 * cos(st.y * lines * TAU);
  col *= mix(1.0, 0.45 + 0.75 * sl, p_scanlines);
  // shadow mask (aperture grille)
  float m = mod(fc.x, 3.0);
  vec3 mask = vec3(m < 1.0 ? 1.0 : 0.55, m >= 1.0 && m < 2.0 ? 1.0 : 0.55, m >= 2.0 ? 1.0 : 0.55);
  col *= mix(vec3(1.0), mask * 1.3, p_mask);
  // rolling refresh bar
  col *= 1.0 + 0.08 * pulse(1.0 - st.y, 1.0, 0.0, 0.06) * p_roll;
  // vignette + glass reflection
  float vig = pow(16.0 * st.x * st.y * (1.0 - st.x) * (1.0 - st.y), 0.25);
  col *= vig;
  col += u_ink * 0.04 * exp(-length(c - vec2(-0.5, 0.55)) * 3.0) * p_glass;
  col = aces(col * 1.15) * inside;
  // bezel
  vec3 bz = u_bg * 0.6 + u_ink * 0.03;
  col = mix(bz, col, inside);
  return vec4(col, 1.0);
}

files.styles/crt-trail.glsl:
// CRT Burn (pass 2) — phosphor persistence: the source a few moments earlier, decaying.
vec4 motif(vec2 uv, vec2 fc) {
  vec3 acc = vec3(0.0);
  // re-render the scene at earlier phases (stateless persistence)
  for (int i = 1; i <= 3; i++) {
    float dp = float(i) * 0.012 * p_persistence;
    vec2 A = M_asp() * 0.5;
    // shift the scene's motion by sampling the source displaced along its dominant motion (approximation)
    acc += texture(u_buf0, (fc - vec2(float(i) * 3.0 * p_persistence, 0.0)) / u_res).rgb * pow(0.55, float(i));
  }
  return vec4(acc, 1.0);
}

files.styles/datamosh.glsl:
// Datamosh (pass 2) — P-frame bleed: macroblocks drag stale pixels along their motion vectors, chroma smears, keyframes snap.
vec4 motif(vec2 uv, vec2 fc) {
  float bs = 8.0 + 24.0 * p_blockSize;
  vec2 blk = floor(fc / bs);
  // time slots between "keyframes"
  float slots = 6.0 * p_rate + 1.0;
  float sl = tslot(slots), sf = tfrac(slots);
  // motion vectors: coherent per region, accumulate within the slot (the bleed)
  vec2 mv = vec2(ln2(blk * 0.12 + sl * 3.7, 1.0, 0.2), ln2(blk * 0.12 - sl * 5.1, 1.0, 0.2));
  float moshing = step(0.35, h11(sl * 1.3)) * p_intensity;
  float grow = pow(sf, 0.7) * moshing;
  vec2 off = mv * bs * 6.0 * grow;
  // some blocks freeze (sample the "previous keyframe" position instead)
  float freeze = step(1.0 - 0.6 * p_freeze * p_intensity, h21(blk + sl));
  vec2 sfc = fc - off * (1.0 - freeze);
  // smear: sample along the motion vector (limited taps)
  vec3 c = vec3(0.0); float wsum = 0.0;
  for (int i = 0; i < 6; i++) { float t = float(i) / 5.0; float w = 1.0 - t * 0.7; c += texture(u_buf0, (sfc - mv * bs * 3.0 * p_smear * t * grow) / u_res).rgb * w; wsum += w; }
  c /= wsum;
  // chroma bleed (shift colour channels within the block)
  vec2 cs = mv * bs * 0.8 * grow * p_chroma;
  c.r = mix(c.r, texture(u_buf0, (sfc + cs) / u_res).r, 0.7);
  c.b = mix(c.b, texture(u_buf0, (sfc - cs) / u_res).b, 0.7);
  // macroblock quantisation artefacts: flatten some blocks to their mean
  if (h21(blk * 1.7 + sl) < 0.3 * p_quantise * p_intensity * moshing) c = texture(u_buf0, ((blk + 0.5) * bs) / u_res).rgb;
  // block edges faintly visible while moshing
  vec2 bf = fract(fc / bs);
  c *= 1.0 - 0.15 * grow * (step(bf.x, 1.0 / bs) + step(bf.y, 1.0 / bs));
  vec3 col = aces(c * 1.1);
  return vec4(col, 1.0);
}

files.styles/drone-swarm.glsl:
// Drone Swarm — a flock of drones morphs between formations over the city while targeting reticles lock and track.
vec2 DS_pos(float i, float N) {
  vec3 h = h33(vec3(i, 4.0, 2.0));
  float a = i / N * TAU;
  // formation morph: ring -> grid -> helix-ish, loop-periodic blend
  float m = 0.5 + 0.5 * lsin(float(p_morphs), 0.0);
  vec2 ring = vec2(cos(a + TAU * u_p * float(p_speed)), sin(a + TAU * u_p * float(p_speed)) * 0.5) * 0.32;
  float gs = ceil(sqrt(N));
  vec2 grid = (vec2(mod(i, gs), floor(i / gs)) / gs - 0.45) * vec2(0.9, 0.5) + vec2(0.05 * lsin(float(p_speed), h.x), 0.0);
  vec2 p = mix(ring, grid, smoothstep(0.2, 0.8, m));
  // boid-like jitter
  p += 0.03 * p_chaos * vec2(ln2(vec2(i, 1.0), float(p_speed), 0.4), ln2(vec2(i, 7.0), float(p_speed), 0.4));
  return p;
}
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  vec3 col = vec3(0.0);
  // city silhouette + haze
  float bx = floor(uv.x * 14.0);
  float bh = -A.y + 0.1 + 0.25 * h11(bx) + 0.1 * h11(floor(uv.x * 37.0));
  float city = step(uv.y, bh);
  col += mix(u_a1 * 0.15, u_bg, sat((uv.y + A.y) * 1.2)) * (1.0 - city) + u_bg * 0.5 * city;
  vec2 wq = uv * vec2(80.0, 60.0);
  col += u_a2 * 0.5 * city * step(0.75, h21(floor(wq))) * step(0.3, fract(wq.x)) * step(0.3, fract(wq.y));
  float N = float(p_drones);
  float sz = 0.012 * p_size;
  for (int i = 0; i < 48; i++) {
    if (i >= p_drones) break;
    float fi = float(i);
    vec2 p = DS_pos(fi, N) + vec2(0.0, 0.08);
    vec2 q = uv - p;
    if (dot(q, q) > 0.01) continue;
    // body: X frame with four rotor discs
    vec2 aq = abs(rot(0.785) * q);
    float arm = min(sdBox(aq, vec2(sz, sz * 0.12)), sdBox(aq.yx, vec2(sz, sz * 0.12)));
    float rotor = 1e9;
    for (int r = 0; r < 4; r++) { vec2 rp = rot(float(r) * 1.5708 + 0.785) * vec2(sz, 0.0); rotor = min(rotor, abs(length(q - rp) - sz * 0.5)); }
    float body = 1.0 - smoothstep(0.0, aa(), min(arm, length(q) - sz * 0.3));
    float rot_ = (1.0 - smoothstep(0.0, aa() * 2.0, rotor - sz * 0.05)) * 0.5;
    // nav light blink (limited)
    float blink = strobe(12.0, 0.5);
    col = mix(col, u_bg * 0.3, body);
    col += u_ink * 0.3 * rot_ + mix(u_a0, u_a1, step(0.5, h11(fi + 3.0))) * exp(-dot(q, q) * 90000.0) * (0.4 + 0.8 * blink) * 1.5;
  }
  // targeting: reticles lock onto a subset, cycling targets
  for (int k = 0; k < 6; k++) {
    if (k >= p_targets) break;
    float slot = floor(u_p * float(p_retargets) + float(k) * 0.37);
    float lockFrac = fract(u_p * float(p_retargets) + float(k) * 0.37);
    float tgt = floor(h11(mod(slot, float(p_retargets)) * 11.0 + float(k) * 3.0) * N);
    vec2 tp = DS_pos(tgt, N) + vec2(0.0, 0.08);
    float s = mix(0.08, 0.025, smoothstep(0.0, 0.3, lockFrac));
    vec2 q = abs(uv - tp);
    float bracket = max(step(q.x, s) * step(s - 0.003, q.x), step(q.y, s) * step(s - 0.003, q.y)) * step(s * 0.6, max(q.x, q.y));
    float cross_ = step(min(q.x, q.y), 0.0012) * step(max(q.x, q.y), s * 0.35) * step(s * 0.12, max(q.x, q.y));
    float locked = smoothstep(0.28, 0.32, lockFrac);
    vec3 rc = mix(u_a2, u_a0, locked);
    col += rc * (bracket + cross_) * 1.2;
    // data tag: bars beside the target
    vec2 tq = uv - tp - vec2(s + 0.01, s * 0.6);
    float bars = step(0.0, tq.x) * step(tq.x, 0.06 * (0.4 + 0.6 * h11(float(k) + slot))) * step(abs(tq.y), 0.003) + step(0.0, tq.x) * step(tq.x, 0.035) * step(abs(tq.y + 0.01), 0.002);
    col += rc * bars * locked * 0.9;
    // tracking line to the frame edge
    col += rc * 0.25 * line(abs(uv.y - tp.y), 0.0008) * step(uv.x, tp.x - s) * locked * p_lines;
  }
  // scanning grid overlay
  vec2 gq = abs(fract(uv * 8.0) - 0.5);
  col += u_a2 * 0.04 * (1.0 - smoothstep(0.0, 0.01, min(gq.x, gq.y))) * p_grid;
  col = aces(col * 1.15);
  return vec4(col, 1.0);
}

files.styles/emp.glsl:
// EMP — an electromagnetic pulse tears through the grid: shock rings warp space, arcs of lightning crawl, static floods the signal.
float EMP_bolt(vec2 uv, vec2 a, vec2 b, float seed, float t) {
  vec2 ab = b - a; float L = length(ab); vec2 dir = ab / L, nn = vec2(-dir.y, dir.x);
  float s = dot(uv - a, dir) / L;
  if (s < 0.0 || s > 1.0) return 0.0;
  float off = 0.0, amp = 0.08 * L;
  for (int i = 0; i < 5; i++) { float fi = float(i); off += amp * (h11(floor(s * pow(2.0, fi + 2.0)) + seed * 17.0 + fi + t * 31.0) - 0.5) * (1.0 - fract(s * pow(2.0, fi + 2.0)) * 0.0); amp *= 0.55; }
  off *= sin(PI * s);
  float d = abs(dot(uv - a, nn) - off);
  return exp(-d * d * 60000.0) + exp(-d * 60.0) * 0.08;
}
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  float ncyc = safeCycles(float(p_pulses)); float cyc = ncyc < 1.0 ? 0.5 : fract(u_p * ncyc);
  // shock ring
  float R = pow(cyc, 0.6) * 1.4 * p_reach;
  float r = length(uv);
  float ring = exp(-pow((r - R) * 25.0 / p_ringWidth, 2.0)) * (1.0 - cyc);
  vec2 warp = normalize(uv + 1e-4) * ring * 0.04 * p_warp;
  vec2 q = uv - warp;
  // background: city grid being hit
  vec2 g = abs(fract(q * 10.0) - 0.5);
  float grid = 1.0 - smoothstep(0.0, 0.03, min(g.x, g.y));
  float hit = smoothstep(R, R - 0.3, r) * (1.0 - cyc);
  vec3 col = mix(u_a2 * 0.25, u_a1 * 0.9, hit) * grid * (0.6 + 0.4 * hit) * p_grid;
  // arcs: bolts between nodes, re-strike each time slot (limited)
  float ts = tslot(16.0 * p_arcRate + 1.0);
  for (int i = 0; i < 6; i++) {
    if (i >= p_arcs) break;
    vec3 h = h33(vec3(float(i), ts, 2.0));
    vec2 a = (h.xy - 0.5) * A * 1.8;
    vec2 b = a + (h33(vec3(float(i), ts, 5.0)).xy - 0.5) * 0.6;
    float bolt = EMP_bolt(q, a, b, float(i), ts);
    float live = step(0.4, h.z) * smoothstep(1.0, 0.0, tfrac(16.0 * p_arcRate + 1.0) * 1.5);
    col += mix(u_a0, u_ink, 0.5) * bolt * live * 1.4;
  }
  col += mix(u_a0, u_ink, 0.4) * ring * 1.2 + u_a0 * exp(-r * 8.0) * flashAmt(exp(-cyc * 20.0)) * p_flash * 2.0;
  // static bursts: horizontal noise bands (limited rate)
  float sb = step(1.0 - 0.3 * p_static, h11(tslot(18.0) + 9.0)) * hit;
  float noise = h21(floor(fc / vec2(2.0, 1.0)) + tslot(18.0) * 13.0);
  col = mix(col, vec3(noise) * mix(u_ink, u_a0, 0.3), sb * 0.6 * p_static);
  // row shift during the pulse
  col *= 1.0 - 0.3 * step(0.8, h21(vec2(floor(fc.y / 6.0), tslot(18.0)))) * hit * p_static;
  col = aces(col * 1.2);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/holo-decay.glsl:
// Holo Decay — a failing hologram: a turning wireframe form, scanlines, tear bands, colour split and dropouts.
float HD_edge(vec3 p, int shape) {
  // wireframe distance: edges of a polyhedron-like form approximated by folded planes
  if (shape == 0) { // icosahedral-ish: abs folds
    p = abs(p); float d = 1e9;
    vec3 n1 = normalize(vec3(1.0, 1.618, 0.0)), n2 = normalize(vec3(0.0, 1.0, 1.618)), n3 = normalize(vec3(1.618, 0.0, 1.0));
    float a = dot(p, n1), b = dot(p, n2), c = dot(p, n3);
    float m = max(a, max(b, c)) - 0.5;
    // edges: where two planes are nearly equal
    d = min(abs(a - b), min(abs(b - c), abs(a - c)));
    return max(abs(m), d * 0.35);
  }
  if (shape == 1) { vec2 q = vec2(length(p.xz) - 0.42, p.y); float th = atan(p.z, p.x), ph = atan(q.y, q.x); float g = min(abs(fract(th * 18.0 / TAU) - 0.5), abs(fract(ph * 10.0 / TAU) - 0.5)); return max(abs(length(q) - 0.16), g * 0.05); }
  // sphere lat/long
  float r = length(p); float th = atan(p.z, p.x), ph = acos(clamp(p.y / max(r, 1e-4), -1.0, 1.0));
  float g = min(abs(fract(th * 16.0 / TAU) - 0.5), abs(fract(ph * 9.0 / PI) - 0.5));
  return max(abs(r - 0.5), g * 0.06);
}
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  float sl = tslot(20.0);
  // tear bands: horizontal slices displaced
  float band = floor((uv.y + A.y) * 14.0);
  float tear = step(1.0 - 0.25 * p_decay, h21(vec2(band, sl))) * (h21(vec2(band, sl + 3.0)) - 0.5) * 0.12 * p_decay;
  vec2 q = uv + vec2(tear, 0.0);
  float ang = TAU * u_p * float(p_spin);
  vec3 col = vec3(0.0);
  for (int ch = 0; ch < 3; ch++) {
    vec2 qo = q + vec2((float(ch) - 1.0) * 0.006 * p_split, 0.0);
    // orthographic ray through the form: march a few samples in depth to find nearest edge
    float best = 1e9;
    for (int k = 0; k < 24; k++) {
      float z = -0.7 + float(k) / 23.0 * 1.4;
      vec3 p = vec3(qo / p_size, z);
      p.xz = rot(ang) * p.xz; p.yz = rot(0.35) * p.yz;
      best = min(best, HD_edge(p, p_shape));
    }
    float w = line(best, 0.012) * 1.0 + glow2(best, 0.02) * 0.25;
    col[ch] = w;
  }
  vec3 tint = mix(u_a1, u_ink, 0.25);
  col = tint * (col.r + col.g + col.b) / 3.0 + vec3(col.r - col.b, 0.0, col.b - col.r) * 0.35 * p_split;
  col = max(col, 0.0);
  // scanlines + rolling bar
  col *= 0.7 + 0.3 * sin(fc.y * PI * 0.5 * p_scanDensity);
  col *= 0.8 + 0.4 * pulse((uv.y + A.y) / (2.0 * A.y), safeCycles(1.0), 0.0, 0.08);
  // projector cone from below
  float cone = exp(-abs(uv.x) * 8.0 / (1.0 + (uv.y + A.y) * 2.0)) * smoothstep(A.y * 0.2, -A.y, uv.y) * 0.15 * p_cone;
  col += u_a1 * cone;
  col += u_a1 * exp(-length((uv - vec2(0.0, -A.y * 0.85)) * vec2(1.0, 4.0)) * 12.0) * p_cone;
  // flicker + dropouts (limited)
  float fl = 1.0 - 0.6 * step(0.8, h11(sl + 7.0)) * p_flicker;
  float drop = step(1.0 - 0.1 * p_decay, h21(vec2(floor(fc.y / 3.0), sl)));
  col *= fl * (1.0 - drop);
  col += u_ink * 0.05 * (h21(fc + sl) - 0.5) * p_noise;
  col = aces(col * 1.5);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/ice-breach.glsl:
// ICE Breach — flying low over wireframe cyberspace: data towers stand guard until a red intrusion wave rips through the grid.
vec4 motif(vec2 uv, vec2 fc) {
  float hz = 0.08 + 0.1 * p_pitch;
  vec3 col = vec3(0.0);
  float travel = u_p * float(p_speed) * 8.0;       // grid cells per loop (multiple of the tower period)
  float cyc = fract(u_p * float(p_breaches));      // intrusion cycle
  if (uv.y < hz) {
    float dy = hz - uv.y;
    float z = 0.25 / dy;
    vec2 g = vec2(uv.x * z * 1.2 * p_gridDensity, z + travel);
    vec2 gf = abs(fract(g) - 0.5);
    float lw = 0.02 + 0.015 * z;
    float grid = max(1.0 - smoothstep(0.0, lw, gf.x * 1.0), 1.0 - smoothstep(0.0, lw, gf.y));
    // intrusion front: expands from a breach point across the grid (in world coords)
    vec2 w = vec2(g.x, g.y - travel);
    vec2 bp = vec2(0.0, 6.0);
    float dist = length(w - bp);
    float front = cyc * 14.0 * p_spread;
    float infected = smoothstep(front, front - 1.0, dist) * (1.0 - smoothstep(0.85, 1.0, cyc));
    float edge = exp(-pow(dist - front, 2.0) * 2.0) * (1.0 - smoothstep(0.85, 1.0, cyc));
    // data packets running along the grid lines
    float pk = pulse(fract(g.y * 0.25), float(p_speed) * 2.0, h11(floor(g.x)), 0.03) * (1.0 - smoothstep(0.0, lw, gf.x));
    vec3 gc = mix(u_a0, u_a1, infected);
    float fade = exp(-z * 0.05);
    col += gc * grid * fade * 0.9 + u_ink * pk * fade * 0.8 * p_packets + u_a1 * edge * fade * 1.5 * grid + u_a1 * edge * 0.15 * fade;
  } else {
    col += mix(u_a0 * 0.08, u_bg, sat((uv.y - hz) * 3.0));
  }
  // data towers: wireframe boxes standing on grid cells, projected in screen space
  for (int i = 0; i < 12; i++) {
    if (i >= p_towers) break;
    vec3 h = h33(vec3(float(i), 3.0, 9.0));
    float gz = floor(h.y * 8.0);
    float zz = mod(gz - travel, 8.0) + 1.0;                // wraps every 8 cells
    float gx = (h.x - 0.5) * 8.0;
    float sy = hz - 0.25 / zz;                            // base on screen
    float sx = gx / (zz * 1.2) ;
    float hgt = (0.4 + 1.6 * h.z) * 0.25 / zz * 3.0 * p_towerHeight;
    float wdt = 0.5 / (zz * 1.2);
    vec2 q = uv - vec2(sx, sy + hgt * 0.5);
    float d = sdBox(q, vec2(wdt * 0.5, hgt * 0.5));
    float wire = 1.0 - smoothstep(0.0, 0.0025, abs(d));
    float inner = step(d, 0.0) * (1.0 - smoothstep(0.0, 0.0025, abs(fract((q.y / hgt + 0.5) * 6.0) - 0.5) * hgt / 6.0 - 0.0));
    // tower gets infected when the front passes its world position
    float inf = smoothstep(cyc * 14.0 * p_spread, cyc * 14.0 * p_spread - 1.0, length(vec2(gx, zz) - vec2(0.0, 6.0))) * (1.0 - smoothstep(0.85, 1.0, cyc));
    vec3 tc = mix(u_a2, u_a1, inf);
    float glitch = inf * step(0.6, h21(vec2(floor(q.y / hgt * 20.0), tslot(24.0) + float(i))));
    float fade = exp(-zz * 0.08) * smoothstep(8.9, 8.0, zz) * smoothstep(1.0, 1.4, zz);
    col = mix(col, u_bg, step(d, 0.0) * 0.85 * smoothstep(8.9, 8.0, zz) * smoothstep(1.0, 1.4, zz));
    col += tc * (wire * 1.3 + inner * 0.4 + exp(-max(d, 0.0) * 60.0) * 0.2 * p_glow) * fade * (1.0 - glitch * 0.8);
  }
  col = aces(col * 1.2);
  return vec4(col, 1.0);
}

files.styles/megastructure.glsl:
// Megastructure — a flight through a brutalist arcology: repeating slabs, neon window bands, fog and traffic in the voids.
vec2 MS_map(vec3 p) {
  float per = 2.0;
  vec3 q = p;
  q.z = mod(q.z, per) - per * 0.5;
  // central canyon: blocks either side
  float side = sign(p.x);
  vec3 b = vec3(abs(p.x) - 1.1 - 0.5 * p_width, p.y, q.z);
  float cell = floor(p.z / per);
  float hgt = 0.6 + 1.2 * h11(cell * 3.0 + side);
  float tower = sdBox3(b - vec3(0.0, hgt * 0.5 - 1.0, 0.0), vec3(0.45, hgt + 1.0, 0.8));
  // stacked slabs cantilever into the canyon
  vec3 s = vec3(abs(p.x) - 0.9, mod(p.y + 0.2, 0.55) - 0.275, q.z);
  float slab = sdBox3(s, vec3(0.35 * p_cantilever, 0.03, 0.6));
  slab = max(slab, p.y - hgt + 0.3);
  // bridges spanning the canyon
  vec3 br = vec3(p.x, p.y - (0.3 + 0.6 * h11(cell + 9.0)), q.z - 0.3);
  float bridge = step(0.5, h11(cell + 17.0)) > 0.5 ? sdBox3(br, vec3(1.5, 0.025, 0.08)) : 1e3;
  float d = min(min(tower, slab), bridge * (p_bridges > 0.5 ? 1.0 : 1e3));
  float mat = d == tower ? 0.0 : d == slab ? 1.0 : 2.0;
  return vec2(d, mat);
}
vec4 motif(vec2 uv, vec2 fc) {
  float per = 2.0;
  float z = u_p * per * float(p_speed) * 2.0;
  vec3 ro = vec3(0.12 * lsin(1.0, 0.0), 0.15 + 0.1 * lsin(1.0, 0.3) + p_height * 0.6, z);
  vec3 fw = normalize(vec3(0.05 * lsin(1.0, 0.6), -0.05 - p_height * 0.1, 1.0));
  vec3 rt = normalize(cross(vec3(0.0, 1.0, 0.0), fw)), up = cross(fw, rt);
  vec3 rd = normalize(fw * 1.4 + uv.x * rt + uv.y * up);
  float t = 0.05; vec2 h = vec2(0.0); float hit = 0.0;
  int steps = 50 + int(70.0 * p_quality);
  for (int i = 0; i < 120; i++) { if (i >= steps) break; h = MS_map(ro + rd * t); if (h.x < 0.001 * t) { hit = 1.0; break; } t += h.x * 0.9; if (t > 30.0) break; }
  vec3 col = vec3(0.0);
  vec3 fogC = mix(u_a1 * 0.25, u_a0 * 0.2, sat(uv.y + 0.4));
  if (hit > 0.0) {
    vec3 p = ro + rd * t;
    vec2 e = vec2(0.002, 0.0);
    vec3 n = normalize(vec3(MS_map(p + e.xyy).x - MS_map(p - e.xyy).x, MS_map(p + e.yxy).x - MS_map(p - e.yxy).x, MS_map(p + e.yyx).x - MS_map(p - e.yyx).x));
    float concrete = 0.5 + 0.5 * snoise(p * 9.0);
    vec3 base = u_bg * 1.5 + u_ink * 0.04 * concrete;
    // window bands on tower faces
    vec2 wg = vec2(p.z * 10.0, p.y * 14.0);
    float win = step(0.35, fract(wg.x)) * step(0.4, fract(wg.y)) * step(0.45, h21(floor(wg))) * step(0.5, abs(n.x));
    vec3 wc = accent(floor(h21(floor(wg) + 3.0) * 3.0));
    // neon strips along slab edges
    float strip = h.y == 1.0 ? exp(-abs(fract(p.y * 1.818 + 0.36) - 0.5) * 40.0) * step(0.5, abs(n.y) < 0.5 ? 1.0 : 0.0) : 0.0;
    float dif = 0.2 + 0.8 * sat(dot(n, normalize(vec3(0.4, 0.8, -0.3))));
    col = base * dif + wc * win * 1.4 * p_windows + u_a0 * strip * 2.0 * p_neon;
    col = mix(col, fogC, 1.0 - exp(-t * 0.12 * p_fog));
  } else {
    col = fogC + u_a1 * 0.2 * exp(-abs(uv.y - 0.1) * 6.0);
  }
  // traffic: light streams in the canyon
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    vec3 hh = h33(vec3(fi, 1.0, 2.0));
    float lane = (hh.x - 0.5) * 1.2, ly = 0.1 + hh.y * 0.9;
    // project a line along z at (lane, ly)
    vec3 a0 = vec3(lane, ly, 0.0) - ro;
    float dz = rd.z; if (dz < 0.01) continue;
    float tt = (lane - ro.x) / max(abs(rd.x), 1e-3);
    vec3 pp = ro + rd * max((ly - ro.y) / (rd.y + sign(rd.y) * 1e-4), 0.0);
    float dx = abs(pp.x - lane) / (0.02 + (pp.z - ro.z) * 0.01);
    float seg = fract(pp.z * 0.3 - u_p * float(p_speed) * 3.0 * (hh.z < 0.5 ? 1.0 : -1.0) + hh.z);
    float dd = step(0.0, (ly - ro.y) / (rd.y + sign(rd.y) * 1e-4)) * exp(-dx * dx * 4.0) * smoothstep(0.0, 0.5, seg) * (1.0 - smoothstep(0.5, 0.52, seg));
    float occl = hit > 0.0 && t < length(pp - ro) ? 0.0 : 1.0;
    col += (hh.z < 0.5 ? u_a0 : u_ink) * dd * 0.6 * p_traffic * occl * exp(-length(pp - ro) * 0.1);
  }
  col = aces(col * 1.3);
  return vec4(col, 1.0);
}

files.styles/neon-rain.glsl:
// Neon Rain — a night street under heavy rain: invented neon signage bleeds into puddles as streaks sheet down.
vec3 NR_signs(vec2 uv) {
  vec2 A = M_asp() * 0.5;
  vec3 col = vec3(0.0);
  for (int i = 0; i < 9; i++) {
    if (i >= p_signs) break;
    vec3 h = h33(vec3(float(i), 2.0, 5.0));
    vec2 c = vec2((h.x - 0.5) * A.x * 1.8, 0.05 + h.y * A.y * 0.8);
    bool vert = h.z < 0.4;
    vec2 sz = vert ? vec2(0.035, 0.11 + 0.1 * h.x) : vec2(0.09 + 0.08 * h.y, 0.035);
    vec2 q = uv - c;
    float d = sdBox(q, sz);
    // glyph blocks inside the sign
    vec2 gc = (q + sz) / (2.0 * sz);
    float n = vert ? 3.0 : 4.0;
    vec2 cell = vert ? vec2(gc.x, gc.y * n) : vec2(gc.x * n, gc.y);
    float gl = CP_glyph(vec2(fract(cell.x), fract(cell.y)) * vec2(1.2, 1.2) - 0.1, floor(vert ? cell.y : cell.x) + h.x * 50.0);
    // flicker (limited)
    float fl = 1.0 - 0.8 * step(0.93 - 0.15 * p_flicker, h11(tslot(24.0) + float(i) * 3.3)) * p_flicker;
    vec3 c3 = accent(floor(h.z * 3.0 + float(i)));
    float tube = 1.0 - smoothstep(0.0, 0.0035, abs(d) - 0.002);
    col += c3 * (tube * 1.6 + gl * step(d, 0.0) * 1.1 + exp(-max(d, 0.0) * 22.0) * 0.35 * p_glow) * fl;
  }
  return col;
}
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  float horizon = -0.08;
  vec3 col = vec3(0.0);
  // sky / buildings silhouette
  float sky = smoothstep(horizon, A.y, uv.y);
  col += mix(u_a1 * 0.12, u_bg, sky) * 0.8;
  float bx = floor(uv.x * 9.0);
  float bh = horizon + 0.15 + 0.35 * h11(bx + 3.0);
  float bld = step(uv.y, bh) * step(horizon, uv.y);
  vec2 wq = vec2(uv.x * 60.0, uv.y * 45.0);
  float win = step(0.82, h21(floor(wq))) * step(0.2, fract(wq.x)) * step(0.3, fract(wq.y));
  col = mix(col, u_bg * 0.6 + accent(bx) * 0.25 * win, bld);
  if (uv.y > horizon) col += NR_signs(uv);
  else {
    // wet street: reflect the signs with ripple distortion and streaky blur
    float dpt = horizon - uv.y;
    vec2 ruv = vec2(uv.x, 2.0 * horizon - uv.y);
    // ripples from drops (loop-periodic)
    vec2 rg = uv * vec2(9.0, 22.0) * p_puddles;
    vec2 rn = floor(rg); vec3 rh = h33(vec3(rn, 4.0));
    float rt = fract(u_p * float(p_speed) * 3.0 + rh.x);
    float rr = length((rg - rn - 0.5 - (rh.xy - 0.5) * 0.4) * vec2(1.0, 2.2)) - rt * 0.5;
    float ring = exp(-rr * rr * 300.0) * (1.0 - rt);
    ruv.x += ring * 0.01 + 0.004 * ln2(uv * vec2(8.0, 40.0), float(p_speed), 0.3) * p_puddles;
    vec3 refl = NR_signs(ruv + vec2(0.0, dpt * 0.3 * ln2(vec2(uv.x * 40.0, 0.0), 1.0, 0.2))) * 0.55 * p_reflection;
    col = u_bg * 0.4 + refl * (0.6 + 0.4 * exp(-dpt * 3.0)) + u_ink * ring * 0.25;
  }
  // rain streaks: several depth layers, falling an integer number of tiles per loop
  for (int l = 0; l < 3; l++) {
    float fl = float(l);
    float cols = 60.0 + fl * 50.0;
    vec2 rq = vec2(uv.x + uv.y * 0.12 * p_wind, uv.y);
    float cx = floor(rq.x * cols);
    vec2 hh = h22(vec2(cx, fl + 7.0));
    if (hh.x > p_density) continue;
    float len = 0.05 + 0.08 * hh.y;
    float y = fract((rq.y + A.y) / (2.0 * A.y) + u_p * float(p_speed) * (2.0 + fl) + hh.y);
    float dx = abs(fract(rq.x * cols) - 0.5) / cols;
    float s = smoothstep(0.0, len, y) * (1.0 - step(len * 1.2, y));
    float streak = (1.0 - smoothstep(0.0, 0.0012 + fl * 0.0005, dx)) * pow(sat(y / len), 2.0) * step(y, len);
    col += mix(u_ink, u_a1, 0.3) * streak * (0.5 - fl * 0.1) * 1.6;
  }
  // fog
  col += u_a1 * 0.06 * p_fog * exp(-abs(uv.y - horizon) * 6.0);
  col = aces(col * 1.2);
  return vec4(col, 1.0);
}

files.styles/net-tunnel.glsl:
// Net Tunnel — racing down an endless data corridor: panels of streaming code, light bars and packet trails rush past.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 q = uv;
  q += 0.04 * p_sway * vec2(lsin(1.0, 0.0), lsin(1.0, 0.25));
  // square tunnel: distance to the nearest wall in "square polar" coordinates
  vec2 aq = abs(q);
  float r = max(aq.x * (1.0 - 0.4 * p_round) + length(q) * 0.4 * p_round, aq.y);
  float z = 0.35 / max(r, 1e-3);                          // depth
  float travel = u_p * float(p_speed) * 8.0;              // integer panels per loop
  float wall = aq.x > aq.y ? (q.x > 0.0 ? 0.0 : 2.0) : (q.y > 0.0 ? 1.0 : 3.0);
  float s = aq.x > aq.y ? q.y / aq.x : q.x / aq.y;        // -1..1 across the wall
  float zz = z + travel;
  vec2 pc = vec2(s * float(p_panels), zz);
  vec2 id = floor(pc), f = fract(pc);
  vec3 h = h33(vec3(id.x + wall * 10.0, mod(id.y, 64.0), 1.0));
  // panel frames
  float frame = 1.0 - smoothstep(0.0, 0.03, min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y)));
  // code rows inside panels (glyph micro-texture)
  vec2 gc = fract(pc * vec2(4.0, 6.0));
  float g = CP_glyph(gc * 1.1 - 0.05, floor(h21(floor(pc * vec2(4.0, 6.0)) + wall) * 40.0));
  float lit = step(0.45, h.x);
  // light bars: rings around the tunnel every few units
  float ringPos = fract(zz / 4.0);
  float ring = exp(-pow((ringPos - 0.5) * 30.0, 2.0)) * p_rings;
  // packet trails: bright streaks moving faster than the camera
  float lane = floor(s * 6.0);
  float pk = pulse(fract(zz * 0.125 + h11(lane + wall * 7.0)), float(p_speed) * 3.0, 0.0, 0.02) * (1.0 - smoothstep(0.0, 0.08, abs(fract(s * 6.0) - 0.5)));
  float fog = exp(-z * 0.12 * p_fog);
  vec3 wc = accent(wall + h.y * 2.0);
  vec3 col = (wc * g * lit * 0.8 * p_code + u_ink * frame * 0.25 + wc * ring * 1.6 + u_ink * pk * 1.8 * p_packets) * fog;
  // end of the tunnel glow
  col += mix(u_a0, u_ink, 0.5) * exp(-r * 20.0) * 0.8 * p_glow;
  col = aces(col * 1.2);
  return vec4(col, 1.0);
}

files.styles/pixel-sort.glsl:
// Pixel Sort (pass 2) — threshold-sorted smears: bright spans melt into ordered gradients along a turning axis.
vec4 motif(vec2 uv, vec2 fc) {
  float ang = p_angle * PI + 0.2 * p_sway * lsin(1.0, 0.0);
  vec2 dir = vec2(sin(ang), -cos(ang));
  float thr = mix(0.03, 0.75, p_threshold) + 0.15 * p_breathe * lsin(1.0, 0.25);
  float hiThr = p_band > 0.99 ? 2.0 : thr + 0.2 + 0.8 * p_band;
  vec3 c0 = texture(u_buf0, fc / u_res).rgb;
  float l0 = luma(c0);
  if (l0 < thr || l0 > hiThr) return vec4(aces(c0), 1.0);
  // walk both ways to find the span within the threshold band
  float stepPx = 2.0 + 4.0 * p_length;
  float back = 0.0, fwd = 0.0;
  vec3 cLo = c0, cHi = c0; float lLo = l0, lHi = l0;
  for (int i = 1; i <= 40; i++) {
    vec3 c = texture(u_buf0, (fc - dir * stepPx * float(i)) / u_res).rgb; float l = luma(c);
    if (l < thr) break; back = float(i);
    if (l < lLo) { lLo = l; cLo = c; } if (l > lHi) { lHi = l; cHi = c; }
  }
  for (int i = 1; i <= 40; i++) {
    vec3 c = texture(u_buf0, (fc + dir * stepPx * float(i)) / u_res).rgb; float l = luma(c);
    if (l < thr) break; fwd = float(i);
    if (l < lLo) { lLo = l; cLo = c; } if (l > lHi) { lHi = l; cHi = c; }
  }
  float span = back + fwd;
  float tpos = span > 0.0 ? back / span : 0.0;
  if (p_reverse) tpos = 1.0 - tpos;
  // the sorted span: a luminance-ordered gradient between its darkest and brightest samples
  vec3 sorted = mix(cLo, cHi, smoothstep(0.0, 1.0, tpos));
  float amt = smoothstep(2.0, 6.0, span) * p_amount;
  vec3 col = mix(c0, sorted, amt);
  col += u_ink * 0.04 * step(0.985, tpos) * amt;
  return vec4(aces(col * 1.05), 1.0);
}

files.styles/signal-loss.glsl:
// Signal Loss (pass 2) — worn videotape: tracking errors roll through, chroma bleeds, dropouts streak, the head switch tears.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  vec2 t = fc / u_res;
  float y = t.y;
  // tracking band travels down the frame (integer passes per loop)
  float band = fract(y + u_p * float(p_roll));
  float trk = exp(-pow((band - 0.5) * 9.0 / (0.3 + p_tracking), 2.0)) * p_tracking;
  float jit = (h21(vec2(floor(fc.y), tslot(30.0))) - 0.5) * 2.0;
  float xoff = trk * (0.02 + 0.03 * jit) + jit * 0.0015 * p_jitter;
  // head-switching noise at the bottom lines
  float hs = smoothstep(0.035, 0.0, y) * p_headSwitch;
  xoff += hs * (0.04 + 0.03 * sin(fc.y * 0.7));
  // wrinkle: sinusoidal skew band
  xoff += p_wrinkle * 0.01 * sin(y * 40.0 + TAU * u_p * 2.0) * smoothstep(0.2, 0.0, abs(y - 0.7 + 0.2 * lsin(1.0, 0.0)));
  vec2 st = vec2(t.x + xoff, t.y);
  // luma sharp, chroma blurred horizontally and shifted (composite video)
  vec3 c0 = texture(u_buf0, st).rgb;
  float Y = luma(c0);
  vec3 cb = vec3(0.0);
  for (int i = -4; i <= 4; i++) cb += texture(u_buf0, st + vec2(float(i) * 0.004 * p_chroma + 0.006 * p_chroma, 0.0)).rgb;
  cb /= 9.0;
  vec3 chroma = cb - luma(cb);
  vec3 col = Y + chroma * (1.0 - 0.5 * trk);
  // tracking noise inside the band
  col += (h21(fc * 0.5 + tslot(30.0)) - 0.5) * trk * 0.8;
  // dropouts: short white horizontal streaks
  vec2 dq = vec2(floor(fc.x / 40.0), floor(fc.y));
  float drop = step(1.0 - 0.004 * p_dropouts, h21(dq + tslot(30.0) * 7.0));
  col = mix(col, u_ink, drop * 0.9);
  // generation loss: softness + saturation drop + noise
  col = mix(col, vec3(luma(col)), 0.2 * p_wear) + (h21(fc + tslot(30.0) * 3.0) - 0.5) * 0.08 * p_wear;
  col *= 1.0 - hs * 0.4;
  col = aces(max(col, 0.0) * 1.05);
  return vec4(col, 1.0);
}

files.styles/smog-sprawl.glsl:
// Smog Sprawl — a layered skyline breathes under smog: lit windows, blinking masts, searchlights and air traffic.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  vec3 col = mix(mix(u_a1 * 0.35, u_a0 * 0.2, sat(uv.y * 2.0 + 0.2)), u_bg, sat(uv.y * 1.5 + 0.1));
  // searchlights
  for (int i = 0; i < 3; i++) {
    if (i >= p_searchlights) break;
    vec2 o = vec2((float(i) - 1.0) * 0.5, -A.y);
    float a = 0.4 * lsin(1.0, float(i) * 0.3) + (float(i) - 1.0) * 0.25;
    vec2 d = vec2(sin(a), cos(a));
    vec2 q = uv - o;
    float al = dot(q, d), pe = abs(dot(q, vec2(-d.y, d.x)));
    col += mix(u_ink, u_a1, 0.5) * exp(-pe / (0.01 + max(al, 0.0) * 0.05)) * step(0.0, al) * 0.18 * exp(-max(al, 0.0) * 1.2);
  }
  // air traffic streaks (behind the front layers)
  for (int i = 0; i < 5; i++) {
    if (i >= p_traffic) break;
    vec3 h = h33(vec3(float(i), 2.0, 9.0));
    float y = 0.05 + h.y * A.y * 0.7;
    float x = (fract(h.x + u_p * float(p_speed) * (h.z < 0.5 ? 1.0 : -1.0)) - 0.5) * 2.4 * A.x;
    vec2 q = uv - vec2(x, y);
    float trail = exp(-q.y * q.y * 40000.0) * exp(-abs(q.x) * 12.0) * step(0.0, q.x * (h.z < 0.5 ? -1.0 : 1.0));
    col += (h.z < 0.5 ? u_a1 : u_ink) * (trail * 0.8 + exp(-dot(q, q) * 60000.0) * 2.0);
  }
  // skyline layers, back to front
  for (int l = 0; l < 4; l++) {
    float fl = float(l);
    float par = (0.02 + fl * 0.02) * p_parallax;
    float x = uv.x + par * lsin(1.0, 0.0) + fl * 3.1;
    float bw = 0.05 + 0.03 * fl;
    float bid = floor(x / bw);
    vec3 h = h33(vec3(bid, fl, 1.0));
    float top = -A.y + (0.25 + 0.45 * h.x * h.x) * (1.2 - fl * 0.2) * p_height + 0.05 * fl * 0.0 - fl * 0.06 + 0.25;
    top -= 0.2 * fl * 0.0;
    float inB = step(uv.y, top);
    // setbacks and spires
    float bx = fract(x / bw);
    float spire = step(0.8, h.y) * step(abs(bx - 0.5), 0.06) * step(uv.y, top + 0.08 * h.z) * step(top, uv.y);
    float mast = step(0.8, h.y) * exp(-dot(vec2((bx - 0.5) * bw, uv.y - top - 0.08 * h.z), vec2((bx - 0.5) * bw, uv.y - top - 0.08 * h.z)) * 60000.0) * step(0.5, fract(u_p * 6.0 + h.z));
    vec3 layerC = mix(u_bg, u_a1 * 0.15, 0.3 / (fl + 1.0)) * (0.5 + fl * 0.15);
    // windows
    vec2 wq = vec2(bx * (3.0 + fl), uv.y * (34.0 + fl * 12.0));
    float win = step(0.4, fract(wq.x)) * step(0.35, fract(wq.y)) * step(1.0 - p_windows * 0.6, h21(floor(wq) + bid * 7.0 + fl));
    vec3 wc = mix(u_a2, u_ink, h21(floor(wq))) * (0.4 + fl * 0.2);
    // holo billboards on some buildings
    float bb = step(0.85, h.z) * step(abs(bx - 0.5), 0.3) * step(abs(uv.y - top + 0.08), 0.04);
    vec3 bbc = accent(bid) * (0.6 + 0.4 * sin(uv.y * 400.0)) * (0.8 + 0.2 * lsin(4.0, h.x));
    vec3 lc2 = layerC + wc * win + bbc * bb * p_billboards;
    // smog between layers
    float smog = p_smog * (0.25 + 0.15 * lfbm(vec2(uv.x * 2.0 + fl, uv.y * 4.0), 3, 1.0, 0.3)) * (1.0 - fl / 4.0) * exp(-(uv.y + A.y) * 1.5);
    col = mix(col, lc2, max(inB, spire));
    col = mix(col, mix(u_a0, u_a1, 0.5) * 0.5, smog);
    col += u_a0 * mast * 2.0;
  }
  col = aces(col * 1.2);
  return vec4(col, 1.0);
}

files.styles/thermal-scan.glsl:
// Thermal Scan — a FLIR sweep over a night street: heat blooms from engines, vents and walkers under a targeting HUD.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  float T = 0.18;                                        // ambient
  // ground plane + building facades with cool windows and warm vents
  float hz = 0.02;
  float facade = step(hz, uv.y);
  T += facade * (0.1 + 0.05 * step(0.5, h21(floor(uv * vec2(18.0, 12.0))))) ;
  vec2 vq = uv * vec2(9.0, 7.0); vec2 vn = floor(vq);
  float vent = step(0.86, h21(vn + 4.0)) * exp(-length(fract(vq) - 0.5) * 6.0) * facade;
  T += vent * (0.5 + 0.2 * lsin(2.0, h21(vn)));
  // steam plumes rising from vents
  float plume = facade * pow(sat(lfbm(vec2(uv.x * 6.0, uv.y * 3.0 - u_p * 0.0) , 4, float(p_speed), 0.4) + 0.2), 3.0) * 0.25 * p_plumes;
  T += plume;
  // road with warm tyre tracks
  float road = (1.0 - facade) * smoothstep(-A.y, hz, uv.y);
  T += road * 0.05;
  // vehicles moving along the road (engines hot)
  for (int i = 0; i < 4; i++) {
    if (i >= p_vehicles) break;
    vec3 h = h33(vec3(float(i), 7.0, 1.0));
    float dir = h.x < 0.5 ? 1.0 : -1.0;
    float x = (fract(h.y + u_p * float(p_speed) * dir) - 0.5) * 2.4 * A.x;
    float y = -A.y * 0.35 - 0.12 * h.z;
    vec2 q = uv - vec2(x, y);
    float body = 1.0 - smoothstep(0.0, 0.01, sdBox(q, vec2(0.11, 0.035)) - 0.01);
    float engine = exp(-length(q - vec2(0.07 * dir, 0.0)) * 40.0);
    float exhaust = exp(-length((q + vec2(0.13 * dir, 0.02)) * vec2(0.6, 3.0)) * 18.0);
    T = mix(T, 0.45, body * 0.8); T += engine * 0.6 + exhaust * 0.3;
  }
  // walkers: warm capsules crossing
  for (int i = 0; i < 8; i++) {
    if (i >= p_walkers) break;
    vec3 h = h33(vec3(float(i), 3.0, 4.0));
    float dir = h.x < 0.5 ? 1.0 : -1.0;
    float x = (fract(h.y + u_p * float(p_speed) * dir) - 0.5) * 2.2 * A.x;
    float y = hz - 0.03 - 0.06 * h.z;
    vec2 q = uv - vec2(x, y + 0.05);
    float bob = 0.004 * sin(TAU * (u_p * float(p_speed) * 20.0 + h.x));
    float bodyD = min(length(q - vec2(0.0, 0.045 + bob)) - 0.012, sdSeg(q, vec2(0.0, 0.03 + bob), vec2(0.0, -0.03)) - 0.011);
    T = max(T, (1.0 - smoothstep(0.0, 0.006, bodyD)) * (0.72 + 0.1 * h.z));
  }
  // scan sweep
  float sweep = pulse((uv.x + A.x) / (2.0 * A.x), float(p_speed), 0.0, 0.02);
  T += sweep * 0.06 * p_sweep;
  // sensor noise and contrast
  T += (h21(fc + tslot(24.0)) - 0.5) * 0.03 * p_noise;
  T = sat((T - 0.12) * mix(1.0, 1.7, p_contrast));
  vec3 col;
  if (p_mode == MODE_WHITE_HOT) col = vec3(T);
  else { vec3 deep = u_bg * 0.6 + vec3(0.07, 0.0, 0.16); col = T < 0.3 ? mix(u_bg, deep, T / 0.3) : T < 0.55 ? mix(deep, u_a1, (T - 0.3) / 0.25) : T < 0.8 ? mix(u_a1, u_a0, (T - 0.55) / 0.25) : mix(u_a0, u_ink, (T - 0.8) / 0.2); }
  // HUD: crosshair, temperature scale, corner brackets
  vec2 cq = abs(uv);
  float ch = (step(cq.x, 0.0012) * step(0.02, cq.y) * step(cq.y, 0.06) + step(cq.y, 0.0012) * step(0.02, cq.x) * step(cq.x, 0.06));
  float scale = step(A.x - 0.06, uv.x) * step(uv.x, A.x - 0.04) * step(abs(uv.y), A.y * 0.6);
  vec3 scC = mix(u_a2, u_a0, (uv.y + A.y * 0.6) / (A.y * 1.2));
  vec2 bq = abs(uv) - A * 0.88;
  float brk = step(0.0, bq.x + 0.06) * step(bq.x, 0.0) * step(abs(bq.y), 0.0015) + step(0.0, bq.y + 0.06) * step(bq.y, 0.0) * step(abs(bq.x), 0.0015);
  col = mix(col, u_ink, (ch + brk) * p_hud);
  col = mix(col, scC, scale * p_hud);
  return vec4(col, 1.0);
}
